# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#1e293b">GALVANİK PİLLERDE AKTİFLİK FARKI, PİL POTANSİYELİ VE PİL ÖMRÜ</text>\n\n  <!-- Sol Kutu: Aktiflik Farkı ve Voltaj Karşılaştırması -->\n  <rect x="18" y="45" width="330" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="183" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">AKTİFLİK FARKI ARTTIKÇA E°(pil) ARTAR</text>\n  <line x1="32" y1="76" x2="334" y2="76" stroke="#93c5fd" stroke-width="1.5"/>\n\n  <!-- Bar 1: Zn-Sn vs Al-Sn -->\n  <text x="32" y="98" font-size="11" font-weight="bold" fill="#1e3a8a">1) Zn - Sn Pili vs. Al - Sn Pili:</text>\n  <rect x="36" y="106" width="95" height="20" rx="4" fill="#60a5fa"/>\n  <text x="138" y="120" font-size="10.5" font-weight="bold" fill="#1e293b">Zn-Sn: 0,627 V</text>\n  <rect x="36" y="130" width="190" height="20" rx="4" fill="#2563eb"/>\n  <text x="234" y="144" font-size="10.5" font-weight="bold" fill="#1d4ed8">Al-Sn: 1,526 V</text>\n\n  <!-- Bar 2: Cr-Ag vs Mg-Ag -->\n  <text x="32" y="170" font-size="11" font-weight="bold" fill="#1e3a8a">2) Cr - Ag Pili vs. Mg - Ag Pili:</text>\n  <rect x="36" y="178" width="110" height="20" rx="4" fill="#34d399"/>\n  <text x="154" y="192" font-size="10.5" font-weight="bold" fill="#1e293b">Cr-Ag: 1,54 V</text>\n  <rect x="36" y="202" width="215" height="20" rx="4" fill="#059669"/>\n  <text x="258" y="216" font-size="10.5" font-weight="bold" fill="#065f46">Mg-Ag: 3,17 V</text>\n  <text x="183" y="236" text-anchor="middle" font-size="9.5" fill="#475569">(Şelale yüksekliği arttıkça potansiyel farkı büyür)</text>\n\n  <!-- Sağ Kutu: Pil Potansiyeli vs Pil Ömrü -->\n  <rect x="364" y="45" width="318" height="198" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="523" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">PİL POTANSİYELİ VE PİL ÖMRÜ ETKENLERİ</text>\n  <line x1="378" y1="76" x2="668" y2="76" stroke="#fcd34d" stroke-width="1.5"/>\n  <text x="380" y="98" font-size="11" font-weight="bold" fill="#92400e">• Pilin büyüklüğü, elektrot kütlesi/yüzeyi,</text>\n  <text x="388" y="114" font-size="11" font-weight="bold" fill="#92400e">çözelti hacmi (Derişim ve T sabitken):</text>\n  <rect x="384" y="122" width="278" height="42" rx="6" fill="#fef3c7" stroke="#f59e0b"/>\n  <text x="523" y="139" text-anchor="middle" font-size="11" font-weight="bold" fill="#b91c1c">→ Pil Potansiyelini (Voltajı) DEĞİŞTİRMEZ!</text>\n  <text x="523" y="157" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">→ Pil Ömrünü (Kapasitesini) UZATIR!</text>\n  <text x="380" y="186" font-size="10.5" fill="#78350f">• Sıcaklık artışı: İstenmeyen tepkimeleri hızlandırıp</text>\n  <text x="388" y="202" font-size="10.5" font-weight="bold" fill="#b91c1c">pil ömrünü AZALTIR.</text>\n  <text x="380" y="226" font-size="10.5" font-weight="bold" fill="#065f46">• Atık piller geri kazanım kutularında toplanmalıdır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">LİTYUM İYON PİLİ YAPISI VE TEPKİMELERİ (E° ≈ 3,4 V)</text>\n\n  <!-- Sol Şema: Anot - Elektrolit - Katot -->\n  <rect x="18" y="44" width="320" height="200" rx="10" fill="#f1f5f9" stroke="#64748b" stroke-width="2"/>\n  <!-- Anot -->\n  <rect x="32" y="68" width="82" height="135" rx="6" fill="#334155" stroke="#0f172a" stroke-width="2"/>\n  <text x="73" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#f8fafc">ANOT (-)</text>\n  <text x="73" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#93c5fd">Grafit</text>\n  <text x="73" y="135" text-anchor="middle" font-size="10" fill="#e2e8f0">Li(k) →</text>\n  <text x="73" y="150" text-anchor="middle" font-size="10" fill="#e2e8f0">Li⁺ + e⁻</text>\n  <text x="73" y="182" text-anchor="middle" font-size="9.5" fill="#fde047">E°=-3,040 V</text>\n\n  <!-- Elektrolit -->\n  <rect x="118" y="68" width="110" height="135" rx="4" fill="#e0f2fe" stroke="#0284c7" stroke-width="1.5" stroke-dasharray="4,3"/>\n  <text x="173" y="90" text-anchor="middle" font-size="11" font-weight="bold" fill="#0369a1">ELEKTROLİT</text>\n  <text x="173" y="108" text-anchor="middle" font-size="9.5" fill="#0c4a6e">Susuz organik</text>\n  <text x="173" y="122" text-anchor="middle" font-size="9.5" fill="#0c4a6e">çözücüde LiPF₆</text>\n  <line x1="128" y1="152" x2="216" y2="152" stroke="#0284c7" stroke-width="2"/>\n  <polygon points="220,152 212,147 212,157" fill="#0284c7"/>\n  <text x="173" y="145" text-anchor="middle" font-size="11" font-weight="bold" fill="#0369a1">Li⁺ göçü</text>\n\n  <!-- Katot -->\n  <rect x="232" y="68" width="92" height="135" rx="6" fill="#1e3a8a" stroke="#1d4ed8" stroke-width="2"/>\n  <text x="278" y="92" text-anchor="middle" font-size="12" font-weight="bold" fill="#f8fafc">KATOT (+)</text>\n  <text x="278" y="112" text-anchor="middle" font-size="11" font-weight="bold" fill="#fde047">CoO₂</text>\n  <text x="278" y="135" text-anchor="middle" font-size="9.5" fill="#e2e8f0">Kobalt(IV) oksit</text>\n  <text x="278" y="160" text-anchor="middle" font-size="10" font-weight="bold" fill="#86efac">LiCoO₂(k)</text>\n  <text x="278" y="176" text-anchor="middle" font-size="9" fill="#dcfce7">oluşur</text>\n\n  <text x="178" y="226" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">Net: Li(k) + CoO₂(k) → LiCoO₂(k)  (≈ 3,4 V)</text>\n\n  <!-- Sağ Kutu: 4 Temel Avantaj -->\n  <rect x="354" y="44" width="328" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">LİTYUM İYON PİLLERİNİN 4 AVANTAJI</text>\n  <line x1="368" y1="76" x2="668" y2="76" stroke="#86efac" stroke-width="1.5"/>\n  <text x="370" y="102" font-size="11" fill="#14532d">1) Mol kütlesi çok küçük (hafif), ürettiği enerji</text>\n  <text x="384" y="118" font-size="11" font-weight="bold" fill="#166534">ve elektrokimyasal potansiyeli en büyüktür.</text>\n  <text x="370" y="144" font-size="11" fill="#14532d">2) Kullanım ve çevrim ömrü uzundur.</text>\n  <text x="370" y="170" font-size="11" fill="#14532d">3) Tekrar şarj edilebilen çevreci pillerdir.</text>\n  <text x="370" y="196" font-size="11" fill="#14532d">4) Geniş bir sıcaklık aralığında çalışabilir:</text>\n  <rect x="384" y="206" width="268" height="26" rx="5" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="518" y="224" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#14532d">Çalışma Aralığı: 10 °C ile 55 °C arası</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
